const PROMPTS = [
  {
    name: 'summarize',
    description: 'Summarize a topic for a given audience.',
    arguments: [
      { name: 'topic', description: 'The topic to summarize.', required: true },
      { name: 'audience', description: 'The target audience.', required: false },
    ],
  },
];

export async function listPrompts() {
  return PROMPTS;
}

function invalidParams(message) {
  const err = new Error(message);
  err.code = -32602;
  return err;
}

export async function getPrompt(name, args = {}) {
  if (name !== 'summarize') {
    throw invalidParams(`Unknown prompt: ${name}`);
  }

  const allowed = new Set(['topic', 'audience']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw invalidParams(`Unexpected argument: ${key}`);
    }
  }

  const topic = args.topic;
  if (topic === undefined || topic === null || topic === '') {
    throw invalidParams('Missing required argument: topic');
  }

  const audience =
    args.audience === undefined || args.audience === null || args.audience === ''
      ? DEFAULT_AUDIENCE
      : args.audience;

  const text = `Summarize the topic "${topic}" for a ${audience} audience.`;

  return {
    messages: [
      {
        role: 'user',
        content: { type: 'text', text },
      },
    ],
  };
}

